package com.example.securewebview

import android.annotation.SuppressLint
import android.net.Uri
import android.os.Bundle
import android.webkit.WebResourceRequest
import android.webkit.WebSettings
import android.webkit.WebView
import android.webkit.WebViewClient
import androidx.appcompat.app.AppCompatActivity

class SecureWebViewActivity : AppCompatActivity() {

    private lateinit var webView: WebView

    private val allowedHosts = setOf(
        "example.com",
        "www.example.com"
    )

    @SuppressLint("SetJavaScriptEnabled")
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        webView = WebView(this)
        setContentView(webView)

        configureSecureWebView(webView)
        loadTrustedUrl("https://example.com")
    }

    @SuppressLint("SetJavaScriptEnabled")
    private fun configureSecureWebView(webView: WebView) {
        with(webView.settings) {
            javaScriptEnabled = false
            domStorageEnabled = false
            allowFileAccess = false
            allowContentAccess = false
            databaseEnabled = false
            mixedContentMode = WebSettings.MIXED_CONTENT_NEVER_ALLOW
            setSupportZoom(false)
            builtInZoomControls = false
            displayZoomControls = false
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
                safeBrowsingEnabled = true
            }
        }

        webView.isLongClickable = false
        webView.setOnLongClickListener { true }
        webView.webViewClient = SecureWebViewClient(allowedHosts)
        webView.clearCache(true)
        webView.clearHistory()
    }

    private fun loadTrustedUrl(url: String) {
        val uri = Uri.parse(url)
        if (isAllowed(uri)) {
            webView.loadUrl(url)
        }
    }

    private fun isAllowed(uri: Uri): Boolean {
        val schemeAllowed = uri.scheme == "https"
        val hostAllowed = uri.host != null && allowedHosts.contains(uri.host)
        return schemeAllowed && hostAllowed
    }
}

private class SecureWebViewClient(
    private val allowedHosts: Set<String>
) : WebViewClient() {

    override fun shouldOverrideUrlLoading(view: WebView?, request: WebResourceRequest?): Boolean {
        val uri = request?.url ?: return true
        return !isAllowed(uri)
    }

    override fun shouldOverrideUrlLoading(view: WebView?, url: String?): Boolean {
        val uri = url?.let(Uri::parse) ?: return true
        return !isAllowed(uri)
    }

    private fun isAllowed(uri: Uri): Boolean {
        return uri.scheme == "https" && uri.host != null && allowedHosts.contains(uri.host)
    }
}
